const cfg = $('Ajustes').first().json;
const lista = v => String(v || '').split(/[,\s;]+/).map(s => s.replace(/\D/g, '')).filter(Boolean);
// Cada grupo: números, plantilla e idioma
const grupos = [
  { to: lista(cfg.to_es), template: cfg.template_es, lang: 'es', locale: 'es-ES' },
  { to: lista(cfg.to_fr), template: cfg.template_fr, lang: 'fr', locale: 'fr-FR' },
];
const fotos = ($input.first().json.momentos || []).slice().sort((a, b) => new Date(a.ts) - new Date(b.ts));
const out = [];
for (const f of fotos) {
  const nota = (f.nota || '').trim().replace(/\s+/g, ' ');
  for (const g of grupos) {
    const hora = new Date(f.ts).toLocaleTimeString(g.locale, { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Madrid' });
    const variable = nota ? `${nota} (${hora})` : `(${hora})`;
    for (const to of g.to) out.push({ json: { url: f.url, variable, phone_number_id: cfg.phone_number_id, to, template: g.template, lang: g.lang } });
  }
}
return out;
